// FileDescriptor type and constants (F01/U01)
typedef int FileDescriptor;
constexpr FileDescriptor invalid_file_descriptor = -1;

// String Manipulation Functions (F01/U01, F02/U02)
std::string StringToLower(std::string str) noexcept;
std::string StringToUpper(std::string str) noexcept;
std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) noexcept;
std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) noexcept;
std::vector<std::string> SplitStringToLines(const std::string& str) noexcept;

// YAML Handling Functions (F01/U01, F02/U02)
YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields = {});
void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field);

// File Descriptor Utility Functions (F01/U01, F02/U02)
bool IsValidFileDescriptor(FileDescriptor fd) noexcept;
void SetFileDescriptorAsNonblocking(FileDescriptor fd);
void ThrowLastSystemError();

// Thread and Backtrace Functions (F01/U01, F02/U02)
std::uint32_t CurrentThreadId() noexcept;
void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip = 0) noexcept;
std::string Backtrace(std::size_t size, std::size_t skip = 0, std::string_view prefix = "") noexcept;

// Smart Pointers & RAII Helpers (F01/U01)
template <typename T, typename... Args>
class Singleton {
public:
  static T& Instance() noexcept {
    static T instance(Args()...);
    return instance;
  }
};

template <typename T, typename... Args>
class SingletonPtr {
public:
  static std::shared_ptr<T> Instance() noexcept {
    static auto instance = std::make_shared<T>(Args()...);
    return instance;
  }
};

template <typename T, typename Cleaner>
class RAII {
public:
  RAII(T obj, Cleaner cleaner) : obj_(obj), cleaner_(cleaner) {}
  ~RAII() { cleaner_(obj_); }
  const T& Object() const noexcept { return obj_; }

private:
  T obj_;
  Cleaner cleaner_;
};

// MappedReadOnlyFile Class (F01/U01, F02/U02)
class MappedReadOnlyFile {
public:
  MappedReadOnlyFile() = default;
  MappedReadOnlyFile(const MappedReadOnlyFile&) = delete;
  MappedReadOnlyFile& operator=(const MappedReadOnlyFile&) = delete;
  MappedReadOnlyFile(MappedReadOnlyFile&&) noexcept {}

  ~MappedReadOnlyFile();

  std::byte* Map(std::string path);
  void Unmap() noexcept;
  size_t Size() const noexcept;
  const std::byte* Data() const noexcept;
  std::string_view Path() const noexcept;

private:
  void Check() const;
  std::byte* mapped_data_ = nullptr;
  size_t file_size_ = 0;
  std::string file_path_;
};

template <typename T, typename U, typename Ret>
concept Addable = requires(T a, U b) {
  {a + b} -> std::convertible_to<Ret>;
};

}
#endif // WS_UTIL_H

#include "util.h"

std::string ws::StringToLower(std::string str) noexcept {
  std::transform(str.begin(), str.end(), str.begin(), ::tolower);
  return str;
}

std::string ws::StringToUpper(std::string str) noexcept {
  std::transform(str.begin(), str.end(), str.begin(), ::toupper);
  return str;
}

std::string ws::ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) noexcept {
  std::string result = std::string(str);
  size_t pos = 0;
  while ((pos = result.find(from, pos)) != std::string::npos) {
    result.replace(pos, from.length(), to);
    pos += to.length();
  }
  return result;
}

std::vector<std::string> ws::SplitString(const std::string& str, const std::regex& pattern) noexcept {
  std::vector<std::string> result;
  std::sregex_token_iterator it(str.begin(), str.end(), pattern, -1);
  std::sregex_token_iterator end;
  while (it != end) {
    result.push_back(*it++);
  }
  return result;
}

std::vector<std::string> ws::SplitStringToLines(const std::string& str) noexcept {
  std::regex newline_regex("\r*\n");
  return SplitString(str, newline_regex);
}

YAML::Node ws::LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields) {
  YAML::Node node = YAML::Load(str.data());
  for (const auto& field : required_fields) {
    if (!node[field]) {
      throw std::invalid_argument("Required field '" + std::string(field) + "' not found in YAML.");
    }
  }
  return node;
}

void ws::ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field) {
  if (!node[field].IsScalar()) {
    throw std::invalid_argument("YAML field '" + std::string(field) + "' is not a scalar.");
  }
}

bool ws::IsValidFileDescriptor(FileDescriptor fd) noexcept {
  return fd >= 0;
}

void ws::SetFileDescriptorAsNonblocking(FileDescriptor fd) {
  if (fcntl(fd, F_SETFL, O_NONBLOCK) == -1) {
    ThrowLastSystemError();
  }
}

void ws::ThrowLastSystemError() {
  throw std::system_error(errno, std::system_category(), "System error occurred.");
}

std::uint32_t ws::CurrentThreadId() noexcept {
  return syscall(__NR_gettid());
}

void ws::Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip) noexcept {
  void* addrlist[size + skip];
  int addrlen = backtrace(addrlist, static_cast<int>(size + skip));
  if (addrlen > 0) {
    char** symbollist = backtrace_symbols(addrlist, addrlen);
    if (symbollist != nullptr) {
      for (int i = skip; i < addrlen; ++i) {
        stack.push_back(symbollist[i]);
      }
      free(symbollist);
    }
  }
}

std::string ws::Backtrace(std::size_t size, std::size_t skip, std::string_view prefix) noexcept {
  std::vector<std::string> stack;
  Backtrace(stack, size, skip);
  std::stringstream ss;
  for (const auto& line : stack) {
    ss << prefix << line << "\n";
  }
  return ss.str();
}

MappedReadOnlyFile::~MappedReadOnlyFile() {
  Unmap();
}

std::byte* MappedReadOnlyFile::Map(std::string path) {
  file_path_ = std::move(path);
  int fd = open(file_path_.c_str(), O_RDONLY);
  if (fd == -1) {
    ThrowLastSystemError();
  }

  struct stat sb;
  if (fstat(fd, &sb) == -1) {
    close(fd);
    ThrowLastSystemError();
  }

  file_size_ = sb.st_size;
  mapped_data_ = static_cast<std::byte*>(mmap(nullptr, file_size_, PROT_READ, MAP_PRIVATE, fd, 0));
  if (mapped_data_ == MAP_FAILED) {
    close(fd);
    ThrowLastSystemError();
  }

  close(fd);
  return mapped_data_;
}

void MappedReadOnlyFile::Unmap() noexcept {
  if (mapped_data_ != nullptr) {
    munmap(mapped_data_, file_size_);
    mapped_data_ = nullptr;
    file_size_ = 0;
  }
}

size_t MappedReadOnlyFile::Size() const noexcept {
  return file_size_;
}

const std::byte* MappedReadOnlyFile::Data() const noexcept {
  return mapped_data_;
}

std::string_view MappedReadOnlyFile::Path() const noexcept {
  return file_path_;
}

void MappedReadOnlyFile::Check() const {
  // Implement file path and permission checks here if needed.
}
